'use strict';
const W=EduWorkspace,E=EduEngine,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>n===null||!Number.isFinite(n)?'—':n.toLocaleString('ru-RU',{maximumFractionDigits:d});const pct=n=>n===null?'—':fmt(n)+'%';const gain=n=>n===null?'—':(n>0?'+':'')+fmt(n,1)+' п. п.';
let state={profile:{...W.defaults},configured:false,tutorialDone:false,rows:W.stamp(E.demo(),W.defaults),source:'demo',file:'',class:'all',book:'all',target:75,min:3,cap:2,approved:null,importMessage:null};
try{const saved=JSON.parse(localStorage.getItem('edulens-v1'));if(saved){const v=E.validate(W.stamp(saved.rows||[],W.defaults));if(!v.errors.length)state={...state,...saved,rows:v.rows,class:'all',book:'all'};}}catch{}
const pages={overview:['Обзор','Большая картина обучения','Понимайте результаты. Находите пробелы. Принимайте обоснованные решения.','▦'],topics:['Анализ тем','Знания в деталях','От общей оценки — к конкретному навыку, которому нужно внимание.','◫'],books:['Учебники','Материалы под микроскопом','Сравнивайте исходный уровень, результаты и наблюдаемый прогресс.','▤'],plan:['Учебные часы','Время на то, что важно','Планируйте поддержку в пределах доступных учебных часов.','◷'],data:['Данные','Хорошие решения начинаются здесь','Загрузите обезличенные результаты или исследуйте демонстрационный набор.','⇧']};
state.profile=W.profile(state.profile);if(W.checkProfile(state.profile).length)state.profile={...W.defaults};
let page='overview';
function persist(){try{localStorage.setItem('edulens-v1',JSON.stringify({school:state.school,profile:state.profile,configured:state.configured,tutorialDone:state.tutorialDone,rows:state.rows,source:state.source,file:state.file,target:state.target,min:state.min,cap:state.cap,approved:state.approved}));return true;}catch{toast('Данные работают в этой вкладке. Сохранить в браузере не удалось.');return false;}}
function contextRows(){return state.rows.filter(r=>W.matches(r,state.profile));}
function filtered(){return contextRows().filter(r=>(!isStudent()||(currentStudent()?.student_id===r.student_id&&currentStudent()?.group===r.class))&&(state.class==='all'||r.class===state.class)&&(state.book==='all'||r.textbook===state.book));}
function topics(){return E.aggregate(filtered(),state.target);}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4300);}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function filters(){
for(const [id,key,label]of[['class-filter','class',state.profile.type==='school'?'Все группы класса':'Все группы курса'],['book-filter','textbook','Все учебники']]){const prop=key==='class'?'class':'book';const values=[...new Set(contextRows().map(r=>r[key]))].sort();if(state[prop]!=='all'&&!values.includes(state[prop]))state[prop]='all';$('#'+id).innerHTML='<option value="all">'+label+'</option>'+values.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('');$('#'+id).value=state[prop];}
const type=W.types[state.profile.type];$('#level-filter-label').textContent=type.unit==='класс'?'Класс обучения':'Курс обучения';$('#group-filter-label').textContent=type.unit==='класс'?'Класс / группа':'Группа';$('#level-filter').innerHTML=Array.from({length:type.max},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+' '+type.unit+'</option>').join('');$('#level-filter').value=state.profile.level;
const subjects=[...new Set([...W.subjects,...state.rows.filter(r=>r.institution_type===state.profile.type).map(r=>r.subject),state.profile.subject])];$('#subject-filter').innerHTML=subjects.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('');$('#subject-filter').value=state.profile.subject;
$('.subject-tag').textContent=state.profile.subject;$('#workspace-settings').innerHTML='<span class="school-icon">'+({school:'▦',college:'▤',university:'⌂'}[state.profile.type])+'</span><div>'+esc(state.profile.name||type.label)+'<small>'+state.profile.level+' '+type.unit+' · Настроить</small></div><span>⌄</span>';
}
function render(){clearSchoolCache();page=location.hash.slice(1);if(!pages[page]||!canVisit(page))page=roleHome();const p=pages[page];$('#nav').innerHTML=Object.entries(pages).filter(([k])=>canVisit(k)&&k!=='plan').map(([k,v])=>'<a href="#'+k+'" class="'+(k===page?'active':'')+'"><span class="nav-icon">'+v[3]+'</span><span class="nav-text">'+v[0]+'</span>'+(k==='topics'?'<span class="nav-count">'+topics().length+'</span>':'')+'</a>').join('');$('#crumb').textContent=p[0];$('#page-title').innerHTML=esc(p[1])+'<span>.</span>';$('#page-desc').textContent=p[2];filters();schoolFilters();$('#source-banner').innerHTML='<div class="source-banner"><span>◉</span><span>'+((contextRows().some(r=>r.demo===true)?'Есть демонстрационные данные · ':contextRows().length?'Рабочие данные · ':'Нет данных · ')+esc(W.caption(state.profile))+' · обработка в браузере.')+'</span><button id="source-data">'+(state.source==='demo'?'О наборе':'Управление')+' ↗</button></div>';$('#source-data').onclick=()=>navigate(isTeacher()?'data':'settings');$('#content').innerHTML=({overview:overview,topics:topicPage,books:bookPage,plan:planPage,data:dataPage,...schoolPages}[page])();bind();bindSetup();bindSchool();decorateShell();}
function navigate(p){if(location.hash==='#'+p)render();else location.hash=p;}
function heat(n){return'<span class="heat '+(n===null?'':n<state.target*2/3?'low':n<state.target?'mid':'high')+'">'+pct(n)+'</span>';}
function panel(title,sub,body,action=''){return'<section class="panel"><div class="panel-head"><div><h2>'+title+'</h2><div class="panel-sub">'+sub+'</div></div>'+action+'</div>'+body+'</section>';}
function metrics(ts){const rs=filtered(),post=E.studentScores(rs,'post'),n=new Set(rs.map(r=>r.student_id)).size,score=E.avg([...post.values()]),pairedPre=E.studentScores(rs,'pre'),ids=[...post.keys()].filter(k=>pairedPre.has(k)),g=E.avg(ids.map(k=>post.get(k)-pairedPre.get(k))),weak=ts.filter(t=>t.post!==null&&t.post<state.target).length;return'<div class="stats">'+[[fmt(n),'Обучающихся в выборке','♧','Групп: '+new Set(rs.map(r=>r.class)).size+' · обезличенные ID',''],[pct(score),'Средний результат','◴','Итоговый тест · '+post.size+' обучающихся',''],[fmt(weak),'Темы для поддержки','⚑','Ниже целевого уровня '+state.target+'%','negative'],[gain(g),'Наблюдаемый прогресс','↗',ids.length+' парных результатов','positive']].map(([v,l,icon,foot,cl])=>'<article class="stat"><div class="stat-top">'+l+'<span class="stat-icon">'+icon+'</span></div><div class="stat-number '+cl+'"><strong>'+v+'</strong></div><div class="stat-foot">'+foot+'</div></article>').join('')+'</div>';}
function chart(ts){return'<div class="panel-body"><div class="legend"><span><i class="dot" style="background:#e1e9d3"></i>До обучения</span><span><i class="dot" style="background:#718b59"></i>После обучения</span></div><div class="chart"><div class="y-grid">'+[100,75,50,25,0].map(n=>'<div><span>'+n+'%</span></div>').join('')+'</div><div class="bars">'+ts.map(t=>'<button class="bar-group" data-topic="'+esc(t.name)+'" title="'+esc(t.name)+': '+pct(t.pre)+' → '+pct(t.post)+'"><div class="bar-area"><div class="bar before" style="height:'+(t.pre||0)+'%"></div><div class="bar after" style="height:'+(t.post||0)+'%"></div></div><span class="bar-label">'+esc(t.name.replace('Обыкновенные ','').replace('Линейные ','').replace('Координатная прямая','Координаты').replace('Геометрические фигуры','Геометрия'))+'</span></button>').join('')+'</div></div><div class="chart-note">↗ Нажмите на тему для подробностей. Разница до и после описывает динамику, но не доказывает причину изменений.</div></div>';}
function insights(ts){const weak=ts.filter(t=>t.post!==null&&t.post<state.target).sort((a,b)=>a.post-b.post);let html=weak.slice(0,2).map(t=>'<div class="insight"><span class="insight-icon">!</span><div><h3>'+esc(t.name)+'</h3><p>'+pct(t.post)+' средний результат; '+pct(t.below*100)+' обучающихся ниже цели. Проверьте задания и базовые навыки.</p><button class="text-link" data-topic="'+esc(t.name)+'">Разобрать тему →</button></div></div>').join('');const limited=ts.filter(t=>t.n<10||t.questions<2||t.incomplete).length;html+='<div class="insight"><span class="insight-icon green">✧</span><div><h3>'+(limited?'Проверьте полноту данных':'Сначала проверка, затем решение')+'</h3><p>'+(limited?limited+' тем с малым объёмом данных. Автоперенос часов для них отключён.':'Сопоставьте условия обучения и проверьте качество заданий перед изменением программы.')+'</p><span class="badge green">Объяснимые рекомендации</span></div></div>';return'<div class="panel-body">'+html+'</div>';}
function heatTable(ts){const classes=[...new Set(filtered().map(r=>r.class))].sort();return'<div class="table-wrap"><table><thead><tr><th>Тема программы</th>'+classes.map(c=>'<th>'+esc(c)+'</th>').join('')+'<th>В среднем</th></tr></thead><tbody>'+ts.map(t=>'<tr><td><button class="table-link" data-topic="'+esc(t.name)+'">'+esc(t.name)+'</button></td>'+classes.map(c=>{const a=E.aggregate(t.rows.filter(r=>r.class===c),state.target)[0];return'<td>'+heat(a?a.post:null)+'</td>';}).join('')+'<td>'+heat(t.post)+'</td></tr>').join('')+'</tbody></table></div><div class="table-bottom"><span>Итоговый тест · средний результат обучающихся</span><span>Цель '+state.target+'%</span></div>';}
function planPreview(ts){const plan=E.makePlan(ts,state),changes=plan.filter(t=>t.hours!==t.proposed),sum=ts.reduce((s,t)=>s+t.hours,0);return'<div class="plan-preview"><span>◷</span><div><strong>'+sum+' ч. Больше внимания сложным темам.</strong><p>Общий объём сохраняется.<br>Каждое изменение проверяет методист.</p></div></div><div class="panel-body">'+(changes.length?changes.slice(0,3).map(t=>'<div class="hour-line"><span>'+esc(t.name)+'</span><span class="hour-change '+(t.proposed<t.hours?'minus':'')+'">'+(t.proposed>t.hours?'+':'')+(t.proposed-t.hours)+' ч</span></div>').join(''):'<p class="small-note">Нет допустимого переноса при текущих данных и ограничениях.</p>')+'<button class="button wide" data-page="plan">Посмотреть план <span>↗</span></button></div>';}
function overview(){const ts=topics();if(!ts.length)return emptyContext();return metrics(ts)+'<div class="grid-main">'+panel('Динамика освоения тем','Результаты входного и итогового тестирования',chart(ts),'<span class="badge green">'+ts.length+' тем</span>')+panel('На что обратить внимание','Сигналы на основе выбранной выборки',insights(ts),'<span style="color:#98a77f">✧</span>')+'</div><div class="bottom-grid">'+panel('Карта освоения','Где обучающимся нужна поддержка',heatTable(ts),'<button class="text-link" data-page="topics">Все темы ↗</button>')+panel('Распределение часов','Рекомендации в пределах учебного плана',planPreview(ts))+'</div>';}
function topicPage(){const ts=topics();if(!ts.length)return emptyContext();return'<div class="callout">Целевой уровень — '+state.target+'%. Доля ниже цели рассчитывается по результатам обучающихся, а не по количеству ошибок. Пороги можно изменить в разделе «Учебные часы».</div><div class="topic-grid">'+ts.map(t=>'<button class="topic-card" data-topic="'+esc(t.name)+'"><span class="badge '+(t.n<10||t.questions<2||t.incomplete?'red':t.post!==null&&t.post>=state.target?'green':'')+'">'+(t.n<10||t.questions<2||t.incomplete?'Нужна проверка':t.post!==null&&t.post>=state.target?'Цель достигнута':'Нужна поддержка')+'</span><div class="eyebrow">ТЕМА ПРОГРАММЫ</div><h3>'+esc(t.name)+'</h3><div class="topic-value">'+pct(t.post)+'</div><p>'+t.n+' обучающихся · '+t.questions+' заданий · '+t.classes.length+' групп<br>Ниже цели: '+pct(t.below===null?null:t.below*100)+' · Прогресс '+gain(t.gain)+'</p><div class="progress"><span style="width:'+(t.post||0)+'%"></span></div><p>Подробнее о результатах ↗</p></button>').join('')+'</div><div class="section-gap">'+panel('Результаты по группам','Итоговое тестирование',heatTable(ts))+'</div>';}
function bookPage(){if(!filtered().length)return emptyContext();const rs=filtered(),books=[...new Set(rs.map(r=>r.textbook))];const groups=books.map(name=>{const rows=rs.filter(r=>r.textbook===name),pre=E.studentScores(rows,'pre'),post=E.studentScores(rows,'post'),ids=[...post.keys()].filter(k=>pre.has(k));return{name,rows,pre:E.avg([...pre.values()]),post:E.avg([...post.values()]),gain:E.avg(ids.map(k=>post.get(k)-pre.get(k))),paired:ids.length,n:post.size,classes:new Set(rows.filter(r=>r.phase==='post').map(r=>r.class)).size};});const ts=topics();return'<div class="callout warning"><b>Описательное сравнение, без причинного рейтинга.</b> Различия могут быть связаны с исходной подготовкой, учителем, часами или составом класса. Для вывода об эффективности нужен сопоставимый дизайн исследования. '+(books.length<2?'Выберите «Все учебники», чтобы сравнить несколько материалов.':'')+'</div><div class="book-cards">'+groups.map(g=>'<article class="book-card"><div class="book-cover">∑</div><h3>'+esc(g.name)+'</h3><div class="book-meta">'+g.n+' обучающихся после обучения · '+g.classes+' групп<br>'+g.paired+' парных результатов<br>'+(state.source==='demo'?'Условный учебник · демоданные':'Из загруженного набора')+'</div><div class="book-metrics"><div><strong>'+pct(g.pre)+'</strong><small>До обучения</small></div><div><strong>'+pct(g.post)+'</strong><small>После обучения</small></div><div><strong>'+gain(g.gain)+'</strong><small>Парный прирост</small></div></div></article>').join('')+'</div>'+panel('Учебники в разрезе тем','Средний итоговый результат и число обучающихся','<div class="table-wrap"><table><thead><tr><th>Тема</th>'+books.map(b=>'<th>'+esc(b)+'</th>').join('')+'</tr></thead><tbody>'+ts.map(t=>'<tr><td>'+esc(t.name)+'</td>'+books.map(b=>{const a=E.aggregate(t.rows.filter(r=>r.textbook===b))[0];return'<td>'+heat(a?a.post:null)+' <span class="panel-sub">n = '+(a?a.n:0)+'</span></td>';}).join('')+'</tr>').join('')+'</tbody></table></div>')+'<div class="section-gap">'+panel('Проверка сопоставимости','Что известно и чего не хватает','<div class="panel-body"><div class="hour-line"><span>Исходный уровень</span><b>'+groups.map(g=>pct(g.pre)).join(' / ')+'</b></div><div class="hour-line"><span>Задания и шкала</span><b>'+esc(checkComparable(groups))+'</b></div><div class="hour-line"><span>Влияние преподавателя и посещаемости</span><span class="badge">Не учтено в MVP</span></div><p class="small-note">Совпадение ID заданий и баллов — техническая проверка. Оно не подтверждает одинаковые условия проведения теста. Прирост рассчитывается только для обучающихся, имеющих оба тестирования.</p></div>')+'</div>';}
function checkComparable(groups){if(groups.length<2)return'Нужны минимум два учебника';const signatures=groups.map(g=>JSON.stringify([...new Set(g.rows.map(r=>JSON.stringify([r.topic,r.question_id,r.phase,r.max_score])))].sort()));return signatures.every(s=>s===signatures[0])?'ID заданий и шкалы совпадают':'Задания или шкалы различаются';}
function signature(plan){return JSON.stringify({school:state.school,profile:state.profile,class:state.class,book:state.book,target:state.target,min:state.min,cap:state.cap,plan:plan.map(t=>[t.name,t.hours,t.proposed])});}
function planPage(){if(!filtered().length)return emptyContext();const ts=topics(),plan=E.makePlan(ts,state),total=plan.reduce((s,t)=>s+t.hours,0),next=plan.reduce((s,t)=>s+t.proposed,0),changes=plan.filter(t=>t.hours!==t.proposed),approved=state.approved&&state.approved.signature===signature(plan);return'<div class="callout">Предложение по правилам: поддержка тем ниже цели за счёт тем с результатом минимум на 5 п. п. выше цели. Перенос возможен при наличии минимум 10 обучающихся и 2 заданий по теме. Это пороги MVP, а не гарантия надёжности. Прогноз роста баллов не рассчитывается.</div><section class="panel"><div class="panel-head"><div><h2>Конструктор учебного плана</h2><div class="panel-sub">Ограничения применяются к каждому переносу</div></div><span class="badge green">'+total+' ч всего</span></div><div class="controls"><label>Цель, % <input id="target" type="number" min="1" max="95" value="'+state.target+'"></label><label>Минимум часов <input id="min-hours" type="number" min="1" max="1000" value="'+state.min+'"></label><label>Макс. перенос, ч <input id="cap-hours" type="number" min="0" max="20" value="'+state.cap+'"></label><button class="button" id="recalculate">Пересчитать</button></div><div class="table-wrap"><table><thead><tr><th>Тема</th><th>Освоение</th><th>Сейчас</th><th>Предложение</th><th>Изменение</th><th>Основание</th></tr></thead><tbody>'+plan.map(t=>'<tr><td>'+esc(t.name)+'</td><td>'+heat(t.post)+'</td><td>'+t.hours+' ч</td><td><b>'+t.proposed+' ч</b></td><td><span class="'+(t.proposed!==t.hours?'hour-change '+(t.proposed<t.hours?'minus':''):'')+'">'+(t.proposed>t.hours?'+':'')+(t.proposed-t.hours)+' ч</span></td><td>'+esc(t.reason)+'</td></tr>').join('')+'</tbody></table></div><div class="summary-row"><span>Общий объём: <b>'+total+' → '+next+' ч</b></span><span>'+changes.length+' изменений · '+(changes.length?'проверьте перед утверждением':'допустимых переносов нет')+'</span></div><div class="panel-body"><p class="small-note">Приоритет: отставание от цели × доля обучающихся ниже цели; каждый уже добавленный час снижает приоритет следующего. Для тем, у которых текущий план ниже заданного минимума, требуется ручная проверка. Изменения не применяются к школьной программе автоматически.</p><button class="button primary" id="approve" '+(!changes.length||approved?'disabled':'')+'>'+(approved?'✓ Предложение утверждено':'Утвердить предложение')+'</button> <button class="button" id="export-plan">↓ Скачать план</button>'+(approved?'<p class="small-note">Утверждено в этом браузере: '+esc(state.approved.time)+'. Базовый план сохранён для сравнения.</p>':'')+'</div></section><div class="section-gap">'+panel('Как проверить эффект','Следующий шаг после решения','<div class="panel-body"><p class="small-note">1. Проверьте базовые навыки и качество теста.<br>2. Уточните ограничения программы и утвердите изменения.<br>3. Проведите повторную диагностику сопоставимыми заданиями.<br>4. Сравните результаты с исходными и, по возможности, с сопоставимой группой.</p></div>')+'</div>';}
function dataPage(){return workspaceDataPage();}
function detail(name){const t=topics().find(x=>x.name===name);if(!t)return;const byQ=[...new Set(t.rows.filter(r=>r.phase==='post').map(r=>r.question_id))].map(q=>{const r=t.rows.filter(r=>r.question_id===q&&r.phase==='post');return{id:q,n:r.length,value:E.avg(r.map(x=>x.score/x.max_score*100))};}).sort((a,b)=>a.value-b.value);const pattern=new Set(t.rows.filter(r=>r.phase==='post').map(r=>r.question_id));const attempts=new Map();t.rows.filter(r=>r.phase==='post').forEach(r=>{if(!attempts.has(r.student_id))attempts.set(r.student_id,new Set());attempts.get(r.student_id).add(r.question_id);});const incomplete=[...attempts.values()].filter(s=>s.size<pattern.size).length;$('#modal-body').innerHTML='<h2>'+esc(name)+'</h2><div class="detail-kpis"><div><b>'+pct(t.post)+'</b>Итоговый результат</div><div><b>'+pct(t.below===null?null:t.below*100)+'</b>Обучающихся ниже цели</div><div><b>'+gain(t.gain)+'</b>Парный прирост</div></div><p>'+t.n+' обучающихся · '+t.questions+' заданий · '+t.classes.length+' групп. Входной результат '+pct(t.pre)+'. Парных результатов: '+t.paired+'.</p><div class="callout '+(t.n<10||t.questions<2||t.incomplete||incomplete?'warning':'')+'">'+(t.n<10||t.questions<2||t.incomplete?'Мало данных: для переноса часов нужны минимум 10 обучающихся и 2 задания.':'Данных достаточно для применения правил MVP. Надёжность педагогического вывода требует отдельной проверки.')+(incomplete?'<br>Неполные комплекты заданий: '+incomplete+' обучающихся. Сравнение может быть искажено.':'')+'</div><h3 style="font-size:13px">Результаты по заданиям</h3><div class="table-wrap"><table><thead><tr><th>Задание</th><th>Средний результат</th><th>Ответов</th></tr></thead><tbody>'+byQ.map(q=>'<tr><td>'+esc(q.id)+'</td><td>'+heat(q.value)+'</td><td>'+q.n+'</td></tr>').join('')+'</tbody></table></div><p>'+(byQ.length?'Начните с проверки задания «'+esc(byQ[0].id)+'»: у него самый низкий средний результат в теме. Без текста задания и ответов нельзя установить конкретную причину ошибки.':'Нет итоговых ответов. Загрузите результаты этапа post.')+'</p><button class="button primary" id="detail-plan">Открыть план часов →</button>';$('#detail').showModal();if(isStudent())$('#detail-plan').hidden=true;$('#detail-plan').onclick=()=>{$('#detail').close();navigate('plan');};}
async function importFile(file){if(!isTeacher())return;if(!file)return;if(file.size>10*1024*1024){feedback('Файл больше 10 МБ',true);return;}try{const prepared=W.prepareImport(E.parseCSV(await file.text()),state.profile);if(prepared.errors.length){feedback(prepared.errors.slice(0,8).join('\n'),true);return;}const result=saveDataset(prepared.rows,importMode,file.name);if(result.errors.length){feedback(result.errors.slice(0,12).join('\n'),true);return;}state.importMessage={error:false,text:'Загружено '+fmt(prepared.rows.length)+' ответов. '+W.caption(state.profile)};render();toast('Данные загружены. Аналитика пересчитана.');}catch(e){feedback(e.message,true);}}
function feedback(text,error){state.importMessage={text,error};const el=$('#import-feedback');if(el)el.innerHTML='<div class="'+(error?'error-list':'success-box')+'">'+esc(text)+'</div>';}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>navigate(el.dataset.page));document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>detail(el.dataset.topic));if(page==='plan'&&$('#recalculate')){$('#recalculate').onclick=()=>{const target=Number($('#target').value),min=Number($('#min-hours').value),cap=Number($('#cap-hours').value);if(!Number.isInteger(target)||target<1||target>95||!Number.isInteger(min)||min<1||min>1000||!Number.isInteger(cap)||cap<0||cap>20){toast('Цель: 1–95%, минимум: 1–1000 ч, перенос: 0–20 ч. Только целые числа.');return;}state.target=target;state.min=min;state.cap=cap;state.approved=null;persist();render();};$('#approve').onclick=()=>{state.approved={signature:signature(E.makePlan(topics(),state)),time:new Date().toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'})};const saved=persist();render();toast(saved?'Предложение утверждено и сохранено в браузере':'Предложение утверждено в этой вкладке');};$('#export-plan').onclick=exportPlan;}}
function exportPlan(){const plan=E.makePlan(topics(),state);download('edulens-plan.csv',E.csv(plan.map(t=>({topic:t.name,result:t.post===null?'':fmt(t.post,2),current_hours:t.hours,proposed_hours:t.proposed,change:t.proposed-t.hours,reason:t.reason})),['topic','result','current_hours','proposed_hours','change','reason']));}
$('#class-filter').onchange=e=>{state.class=e.target.value;render();};$('#book-filter').onchange=e=>{state.book=e.target.value;render();};$('#import-top').onclick=()=>navigate('data');$('#export').onclick=()=>{if(page==='plan')return exportPlan();download('edulens-report.csv',E.csv(topics().map(t=>({topic:t.name,pre:t.pre,post:t.post,gain:t.gain,institution:W.types[state.profile.type].label,level:state.profile.level,subject:state.profile.subject,students:t.n,questions:t.questions,below_target:t.below,hours:t.hours})),['topic','pre','post','gain','institution','level','subject','students','questions','below_target','hours']));toast('Отчёт скачан');};$('#close-modal').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};$('#guide-btn').onclick=()=>startTutorial();window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
